import json
from html import escape
from pathlib import Path


ROOT = Path(__file__).parent
DATA_FILE = ROOT / "conversation_banks.json"
OUTPUT_FILE = ROOT / "conversation_banks.html"


def main():
    banks = json.loads(DATA_FILE.read_text(encoding="utf-8"))
    data = json.dumps(banks, ensure_ascii=True).replace("</", "<\\/")
    html = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Daily English | Daily Meeting Banks</title><style>
:root{{--ink:#17202a;--muted:#687582;--line:#dce3e8;--canvas:#f4f6f8;--white:#fff;--blue:#1769aa;--navy:#172c3d}}*{{box-sizing:border-box}}body{{margin:0;background:var(--canvas);color:var(--ink);font:14px Georgia,serif}}button,input,select{{font:inherit}}button{{cursor:pointer}}.app{{min-height:100vh}}.topbar{{height:64px;background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;padding:0 32px;gap:28px}}.brand{{font:700 19px Georgia,serif}}.brand span{{color:var(--blue)}}.nav{{display:flex;gap:22px;color:var(--muted)}}.nav .active{{color:var(--blue);font-weight:700;border-bottom:2px solid var(--blue);padding:23px 0 20px}}main{{max-width:1500px;margin:auto;padding:32px}}.intro{{display:flex;justify-content:space-between;align-items:end;gap:28px;margin-bottom:28px}}.eyebrow{{font:700 11px Arial,sans-serif;color:var(--blue);letter-spacing:1.6px;text-transform:uppercase;margin:0 0 8px}}h1{{font-size:34px;margin:0 0 6px}}.intro p:last-child{{color:var(--muted);margin:0;max-width:600px}}.stats{{display:flex;gap:24px;text-align:right}}.stat strong{{display:block;font-size:25px;color:var(--navy)}}.stat span{{color:var(--muted);font:11px Arial,sans-serif;text-transform:uppercase;letter-spacing:.8px}}.toolbar{{display:flex;gap:10px;margin-bottom:22px;align-items:center}}.search,.filter{{background:#fff;border:1px solid var(--line);border-radius:4px;padding:10px 12px;color:var(--ink)}}.search{{width:310px}}.summary{{margin-left:auto;color:var(--muted);font-size:13px}}.layout{{display:grid;grid-template-columns:280px 1fr;gap:22px;align-items:start}}.bank-list{{display:grid;gap:8px}}.bank{{background:#fff;border:1px solid var(--line);border-left:4px solid var(--bank-color);border-radius:4px;padding:14px;text-align:left;color:var(--ink)}}.bank:hover,.bank.selected{{border-color:var(--bank-color);box-shadow:0 2px 8px #17202a12}}.bank.selected{{background:#fbfcfd}}.bank-name{{font-weight:700;display:block;margin-bottom:5px}}.bank-meta{{color:var(--muted);font:11px Arial,sans-serif}}.library{{display:grid;grid-template-columns:repeat(2,minmax(260px,1fr));gap:14px}}.conversation{{background:#fff;border:1px solid var(--line);border-radius:5px;padding:17px;text-align:left;min-height:178px;display:flex;flex-direction:column}}.conversation:hover{{border-color:var(--blue);box-shadow:0 3px 12px #17202a12}}.conversation-top{{display:flex;justify-content:space-between;align-items:center;gap:12px}}.conversation h2{{font-size:19px;line-height:1.2;margin:12px 0 8px}}.conversation p{{color:var(--muted);line-height:1.4;margin:0 0 16px}}.level{{color:var(--bank-color);font:700 11px Arial,sans-serif}}.duration{{color:var(--muted);font:11px Arial,sans-serif}}.goal{{margin-top:auto;font:12px Arial,sans-serif;color:var(--navy)}}.detail-backdrop{{position:fixed;inset:0;background:#17202a66;display:none;place-items:center;padding:20px}}.detail-backdrop.open{{display:grid}}.detail{{background:#fff;border-radius:6px;max-width:680px;width:100%;max-height:90vh;overflow:auto;padding:26px;box-shadow:0 12px 40px #17202a33}}.detail-head{{display:flex;justify-content:space-between;gap:20px;align-items:start}}.close{{border:0;background:transparent;color:var(--muted);font-size:22px}.detail h2{{font-size:28px;margin:12px 0 8px}}.detail-subtitle{{color:var(--muted);margin:0 0 22px}}.turns{{display:grid;gap:10px}}.turn{{padding:12px 14px;border-left:3px solid var(--turn-color);background:#f7f9fa;border-radius:0 4px 4px 0}}.speaker{{display:block;color:var(--turn-color);font:700 11px Arial,sans-serif;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px}}.turn-text{{line-height:1.45}}@media(max-width:900px){{main{{padding:22px 16px}}.layout{{grid-template-columns:1fr}}.bank-list{{grid-template-columns:repeat(3,1fr)}}.intro{{display:block}}.stats{{margin-top:20px;text-align:left}}}}@media(max-width:620px){{.topbar{{padding:0 16px}}.nav{{display:none}}.toolbar{{flex-wrap:wrap}}.search{{width:100%}}.summary{{margin-left:0}}.bank-list,.library{{grid-template-columns:1fr}}}}
</style></head><body><div class="app"><header class="topbar"><div class="brand">Daily <span>English</span></div><nav class="nav"><span>Boards</span><span class="active">Daily meetings</span></nav></header><main><section class="intro"><div><p class="eyebrow">Practice library / Client delivery</p><h1>Daily meeting banks</h1><p>Choose a sector, join a client meeting and practise reporting progress, blockers and next steps.</p></div><div class="stats"><div class="stat"><strong id="bank-count"></strong><span>Companies</span></div><div class="stat"><strong id="conversation-count"></strong><span>Daily meetings</span></div></div></section><div class="toolbar"><input class="search" id="search" type="search" placeholder="Search daily meetings..." aria-label="Search daily meetings"><select class="filter" id="level" aria-label="Filter by level"><option value="">All levels</option><option>A2</option><option>B1</option><option>B2</option><option>C1</option></select><span class="summary" id="summary"></span></div><div class="layout"><aside class="bank-list" id="bank-list"></aside><section class="library" id="library"></section></div></main><div class="detail-backdrop" id="detail-backdrop" role="dialog" aria-modal="true"><section class="detail"><div class="detail-head"><span class="eyebrow" id="detail-bank"></span><button class="close" id="detail-close" aria-label="Close daily meeting">&times;</button></div><h2 id="detail-title"></h2><p class="detail-subtitle" id="detail-context"></p><p class="detail-subtitle" id="detail-goal"></p><div class="turns" id="turns"></div></section></div></div><script>
const banks=__BANK_DATA__;let selectedBank=banks[0].id;const list=document.querySelector('#bank-list'),library=document.querySelector('#library'),search=document.querySelector('#search'),level=document.querySelector('#level'),summary=document.querySelector('#summary'),details=document.querySelector('#detail-backdrop');document.querySelector('#bank-count').textContent=banks.length;document.querySelector('#conversation-count').textContent=banks.reduce((total,bank)=>total+bank.conversations.length,0);
function renderBanks(){{list.innerHTML=banks.map(bank=>`<button class="bank ${{bank.id===selectedBank?'selected':''}}" style="--bank-color:${{bank.color}}" data-bank="${{bank.id}}"><span class="bank-name">${{bank.name}}</span><span class="bank-meta">${{bank.industry}} &middot; ${{bank.conversations.length}} conversations</span></button>`).join('');list.querySelectorAll('.bank').forEach(button=>button.addEventListener('click',()=>{{selectedBank=button.dataset.bank;renderBanks();renderLibrary()}}))}}
function renderLibrary(){{const bank=banks.find(item=>item.id===selectedBank);const query=search.value.toLowerCase(),wantedLevel=level.value;const conversations=bank.conversations.filter(item=>(!query||`${{item.title}} ${{item.client}} ${{item.provider}} ${{item.project}} ${{item.goal}}`.toLowerCase().includes(query))&&(!wantedLevel||item.level===wantedLevel));library.innerHTML=conversations.map((item,index)=>`<button class="conversation" style="--bank-color:${{bank.color}}" data-index="${{bank.conversations.indexOf(item)}}"><div class="conversation-top"><span class="level">${{item.level}}</span><span class="duration">${{item.duration}}</span></div><h2>${{item.title}}</h2><p class="meeting-context">${{item.client}} &middot; ${{item.provider}}</p><p>${{item.goal}}</p><span class="goal">Open daily &rarr;</span></button>`).join('')||'<p>No daily meetings match these filters.</p>';summary.textContent=`${{conversations.length}} of ${{bank.conversations.length}} daily meetings`;library.querySelectorAll('.conversation').forEach(card=>card.addEventListener('click',()=>showDetails(bank,bank.conversations[Number(card.dataset.index)])))}}
function showDetails(bank,conversation){{document.querySelector('#detail-bank').textContent=bank.name;document.querySelector('#detail-title').textContent=conversation.title;document.querySelector('#detail-context').textContent=`Client: ${{conversation.client}} · Delivery team: ${{conversation.provider}} · Project: ${{conversation.project}}`;document.querySelector('#detail-goal').textContent=`${{conversation.goal}} ${{conversation.level}} · ${{conversation.duration}}`;document.querySelector('#turns').innerHTML=conversation.turns.map((turn,index)=>`<div class="turn" style="--turn-color:${{index%2?'#1769aa':bank.color}}"><span class="speaker">${{turn.speaker}}</span><span class="turn-text">${{turn.text}}</span></div>`).join('');details.classList.add('open')}}
[search,level].forEach(control=>control.addEventListener('input',renderLibrary));document.querySelector('#detail-close').addEventListener('click',()=>details.classList.remove('open'));details.addEventListener('click',event=>{{if(event.target===details)details.classList.remove('open')}});renderBanks();renderLibrary();
</script></body></html>'''
    html = html.replace("__BANK_DATA__", data).replace("{{", "{").replace("}}", "}")
    OUTPUT_FILE.write_text(html, encoding="utf-8")
    print(f"Conversation library generated: {OUTPUT_FILE.name}")


if __name__ == "__main__":
    main()
